#!/usr/bin/env python3
"""Independent narrow source wiring checks; no claim of native lifecycle/UI execution."""
from pathlib import Path
import json, re, sys
repo = Path(sys.argv[1]).resolve()
base = repo / 'app/src/main/kotlin/com/easysavevideo/app'
read = lambda name: (base / name).read_text()
policy = read('browser/bookmarks/BookmarkPolicy.kt')
controller = read('browser/bookmarks/BookmarkController.kt')
store = read('browser/bookmarks/AndroidBookmarkStorage.kt')
runtime = read('browser/bookmarks/AndroidBookmarkRuntime.kt')
panel = read('browser/bookmarks/BookmarkPanel.kt')
host = read('browser/SystemBrowserHost.kt')
screen = read('ui/BrowserScreen.kt')
activity = read('MainActivity.kt')
checks = {}
def check(label, condition): checks[label] = bool(condition)
check('pure policy/controller contain no platform imports', 'import android.' not in policy + controller)
check('bookmark package has no network or WebView load primitive', not re.search(r'\b(?:loadUrl|loadData|evaluateJavascript|openConnection|openStream|HttpClient|OkHttpClient|WebView)\s*\(', '\n'.join(p.read_text() for p in (base/'browser/bookmarks').glob('*.kt'))))
check('store resolves no-backup directory lazily', 'by lazy' in store and 'app.noBackupFilesDir' in store)
check('store sync precedes finish and confirms readable committed records', store.index('stream.fd.sync()') < store.index('file.finishWrite(stream)') < store.index('check(load() == items)'))
check('store bounds streaming bytes and rejects zero-progress reads', 'BookmarkCodec.MAX_BYTES + 1 - buffer.size()' in store and 'check(read > 0)' in store and 'buffer.size() <= BookmarkCodec.MAX_BYTES' in store)
check('runtime uses app-owned singleton', '@Volatile private var instance' in runtime and 'AndroidBookmarkRuntime(context.applicationContext)' in runtime and 'bookmarks = AndroidBookmarkRuntime.get(applicationContext)' in activity)
check('runtime uses serial worker and main dispatcher', 'newSingleThreadExecutor()' in runtime and 'worker.execute(work)' in runtime and 'main.post(result)' in runtime)
check('worker failure cannot publish success', 'result.fold(onSuccess' in controller and 'onFailure = { unavailable() }' in controller)
check('single operation and completion generation gate', '!state.busy' in controller and '!closed && generation == operation && state.busy' in controller)
check('host capture requires current entry and exact live/admitted URL', 'if (current(entry) == null) return null' in host and 'BookmarkPolicy.capture(tab, entry.view.url, entry.bookmarkAddress, entry.view.title' in host)
check('host uses identity-aware live token revalidation', 'BookmarkPolicy.accept(expected, bookmarkPage())' in host)
check('same-document callback verifies current entry READY and live origin', 'current(entry) != null && tab?.loadState == BrowserLoadState.READY && view.url == actual' in host and 'BrowserInputPolicy.origin(actual) == BrowserInputPolicy.origin(tab.address?.value)' in host)
check('explicit open validates current entry in both layouts', screen.count('bookmarks.addressForOpen(item)?.let { target ->') == 2 and screen.count('focus.clearFocus(); browser.navigate(target)') == 2)
check('list-only state is saveable without stored destination', 'var bookmarksOpen by rememberSaveable { mutableStateOf(false) }' in screen and 'rememberSaveable' not in panel)
check('phone/tablet use list plus modal/sidebar', 'bookmarksOpen && wide' in screen and 'bookmarksOpen && !wide' in screen and 'Modifier.width(360.dp)' in screen and 'LazyColumn(Modifier.fillMaxSize()' in panel)
check('keyboard/back/dismiss cannot trigger opening', '.systemBarsPadding().imePadding()' in screen and 'if (bookmarksOpen) { bookmarksOpen = false; focus.clearFocus() }' in screen and screen.count('onClose = { bookmarksOpen = false; focus.clearFocus() }') == 2)
check('URL display is bounded and directional', 'TextDirection.Ltr' in panel and 'maxLines = 3' in panel and 'maxLines = 2' in panel)
check('list rows contain no images or actionable URI parsing', all(t not in panel for t in ['AsyncImage(', 'Image(', 'AndroidView(', 'Uri.parse(', 'loadUrl(']))
check('unavailable items cannot open or mutate', 'state.ready && !state.busy' in panel and '!closed && state.ready && !state.busy' in controller)
check('history reload is never admitted as same-document', '!isReload &&' in host)
check('ambiguous missing storage never becomes writable empty', 'Files.newDirectoryStream(parent)' in store and 'Files.notExists(base, LinkOption.NOFOLLOW_LINKS)' in store)
check('ordinary capture excludes incognito and unready page', 'tab.incognito' in policy and 'tab.loadState != BrowserLoadState.READY' in policy and 'tab.epoch <= 0' in policy)
check('new store has no session/history/settings import', all(t not in store + runtime + controller for t in ['BrowserPersistence', 'AndroidBrowserSessionStore', 'SettingsStore', 'BrowserSessionCheckpoint', 'CookieManager']))
result = {'review_scope':'Ordinary bookmark wiring only, on the exact authorized media-close integration', 'hotfix_inclusive_baseline':'0c178320cd78391bfedd5f9846e3ee873f0f5fce', 'combined_integration':'c3792eac3f98c87c4ea55331a271124d89e64829', 'hotfix_runtime_status':'NOT ASSESSED; device QA pending', 'pass':all(checks.values()), 'checks':checks, 'count':len(checks), 'limits':['Source wiring only; not native Android UI, lifecycle, filesystem, WebView, or rotation acceptance.','No network, Gradle, APK or device operations are executed by this script.']}
print(json.dumps(result,indent=2))
raise SystemExit(0 if result['pass'] else 1)
